solutions.javascript:
function jumlahRekursif(arr) {
  if (arr.length === 0) return 0;
  return arr[0] + jumlahRekursif(arr.slice(1));
}

solutions.python:
def jumlah_rekursif(arr):
    if not arr:
        return 0
    return arr[0] + jumlah_rekursif(arr[1:])

